import type { EngineInterface, Register } from 'claude-code'

const inFlight = new Set<string>()

async function colorize($: EngineInterface): Promise<void> {
  const session = await $.session.id()
  if (inFlight.has(session)) return
  inFlight.add(session)
  $.clock.after(0, () => {
    $.command.run({ command: 'color' })
      .then(() => $.store.set(session, true))
      .catch((err: unknown) => $.ui.log(String(err)))
      .finally(() => inFlight.delete(session))
  })
}

export const register: Register = (on) => {
  let running = false
  let pending = false

  on('turn.start', async ($, e, next) => {
    running = true
    return next(e)
  })

  on('turn.complete', async ($, e, next) => {
    const result = await next(e)
    if (e.agentId === undefined) {
      running = false
      if (pending) {
        pending = false
        await colorize($)
      }
    }
    return result
  })

  on('command.run', { command: ['rename', 'branch', 'color'] }, async ($, e, next) => {
    const result = await next(e)
    const session = await $.session.id()
    if (e.command === 'color') {
      pending = false
      await $.store.set(session, true)
    } else if (e.command === 'branch' || (await $.store.get(session)) === undefined) {
      if (running) pending = true
      else await colorize($)
    }
    return result
  })
}

